INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (371478, 15415, 'South China Morning Post', 'en', 'Fake troops loot earthquake-hit homes in Japan’s Kumamoto', 'https://www.scmp.com/week-asia/health-environment/article/3364410/fake-troops-loot-earthquake-hit-homes-japans-kumamoto', 'Men in military fatigues identical to those worn by Japan’s Ground Self-Defence Forces (SDF) are reportedly prowling evacuated communities in Kumamoto prefecture to loot abandoned homes and businesses in the aftermath of last month’s earthquake. An official at the prefectural government confirmed media reports of “fake SDF personnel” attempting to enter properties in affected areas, although she said the authority’s immediate priority was still to find shelter and provide food and medical care...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/18/5098e927-a828-4383-9b96-1a7da8cde80f_6646de63.jpg?itok=_xA8QZbZ&v=1787038771', '2026-08-18T07:58:57+00:00', '2026-08-18T08:24:26.011679'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
