INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (365032, 15418, 'The Times of India', 'en', 'CEA bats for E10 fuel; not feasibile, say officials', 'https://timesofindia.indiatimes.com/india/cea-bats-for-e10-fuel-not-feasibile-say-officials/articleshow/133309557.cms', 'Officials were taken aback by the Chief Economic Adviser''s comments regarding the availability of E10 fuel, which could spark a shift towards lower ethanol blends. Nonetheless, the government is not currently considering the introduction of E10 at fuel stations. Logistical challenges and the necessary infrastructure for managing E10 are cited by officials, who also point out that studies indicate E20 fuel does not pose mechanical risks to older vehicles.', 'https://static.toiimg.com/photo/msid-133309588,imgsize-112021.cms', '2026-08-18T02:16:27+00:00', '2026-08-18T03:05:25.448074'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
