INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (372752, 15443, 'Associated Press', 'en', 'Ukraine aims a drone blitz at Moscow while Russian missiles kill 10 in a Ukrainian village', 'https://news.google.com/rss/articles/CBMinwFBVV95cUxNZWNZbnhPNkw5SFowb3FVbzZYN2VIbThFU0ZnckM0eHdHSmdwanEwbHM4eGxLN1Z4bnBoeFZhS2dBNGNWTHFZNjBVWTN6ZGRuRm4yZ3VwalBPTFJ3dUhiQnd2TE5BZkhLMW9vd2pWam5DcmdVOUpCR3JObnN1YV9nMUJBcngya1RvQkRVRXRYUjdqLWFaYllkSTFHbDQwUTA?oc=5', 'Ukraine aims a drone blitz at Moscow while Russian missiles kill 10 in a Ukrainian village apnews.com', '', '2026-08-18T09:21:00+00:00', '2026-08-18T10:06:06.080451'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (372771, 15443, 'Deutsche Welle', 'en', 'Ukraine, Russia trade strikes; Wildberries site hit again', 'https://www.dw.com/en/ukraine-russia-trade-strikes-wildberries-site-hit-again/a-78408178?maca=en-rss-en-world-4025-xml-mrss', 'Ukriane reported 10 dead in a missile strike in the northeastern Kharkiv oblast near the border. Russia, meanwhile, reported more than 600 drones approaching the Moscow area and warned the UK on suppyling drones to Kyiv.', '', '2026-08-18T09:29:00+00:00', '2026-08-18T10:06:26.501311'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (372781, 15443, 'France 24', 'en', 'Ukraine launches over 600 drones at Moscow region', 'https://www.france24.com/en/ukraine-launches-over-600-drones-at-moscow-region', 'We start the programme with the latest in the Russia-Ukraine war. Early this morning, Ukraine launched over 600 drones at the Moscow region, in one of its biggest air assaults on the Russian capital. At least three ​people, including a 10-year-old girl, were injured in the region. Meanwhile, a Russian attack on the Kharkiv region in northeast Ukraine has killed ten people. Details by FRANCE 24 correspondent in Kyiv, Emmanuelle Chaze.', 'https://s.france24.com/media/display/53506f00-9ae6-11f1-97cb-005056bf30b7/w:1024/p:16x9/EN-20260818-110115-110602-CS.jpg', '2026-08-18T09:57:00+00:00', '2026-08-18T10:06:30.703481'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
