INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (373015, 15443, 'The Independent', 'en', 'Russia fires top economist after warning over Ukraine war costs: ‘We are falling behind’', 'https://www.independent.co.uk/news/world/europe/russia-putin-veb-bank-economist-fired-andrey-klepach-b3034772.html', 'The economist’s claims come as Ukraine has repeatedly attacked Russia’s oil refineries and largest retailer Wildberries this summer', 'https://static.independent.co.uk/2026/08/17/13/2026-08-17T122158Z_2114871647_RC2USU990RGI_RTRMADP_3_UKRAINE-CRISIS-RUSSIA-VEB.JPG?width=1200&auto=webp&trim=43%2C0%2C43%2C0', '2026-08-18T09:25:29+00:00', '2026-08-18T10:08:29.323279'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (373124, 15443, 'South China Morning Post', 'en', 'Ukraine vows to respond after Russian strike kills 10 in northeast region', 'https://www.scmp.com/news/world/russia-central-asia/article/3364429/ukraine-vows-respond-after-russian-strike-kills-10-northeast-region', 'A Russian attack on a village in the Kharkiv region of northeast Ukraine killed 10 people, Kyiv said on Tuesday, vowing to respond. The strike comes amid a surge in civilian deaths in the four-and-a-half-year war. Russian forces “carried out a rocket strike on Pechenihy”, a village around 40km (25 miles) from the Russian border, Kharkiv regional governor Oleg Synegubov said on social media. “According to preliminary information, 10 people were killed,” he added, with 17 people wounded. Ukrainian...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/18/13f9d7e3-caef-444f-9713-002f040a525f_2b63e8cf.jpg?itok=sL4BxVpD&v=1787044504', '2026-08-18T09:30:25+00:00', '2026-08-18T10:10:32.384602'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
