INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (367018, 15445, 'The Economic Times', 'en', 'Global Market: Japan stocks slide as oil spike and rising bond yields weigh on sentiment', 'https://economictimes.indiatimes.com/markets/us-stocks/news/global-market-japan-stocks-slide-as-oil-spike-and-rising-bond-yields-weigh-on-sentiment/articleshow/133310581.cms', 'Japan’s Nikkei fell 1.1%, ending its five-session rally as Middle East tensions disrupted oil supplies and revived inflation concerns. Rising crude prices and bond yields pressured equities, while shipping stocks gained on expectations of higher freight rates. Technology shares were mixed as investors assessed geopolitical risks, valuations and corporate earnings prospects.', 'https://img.etimg.com/photo/msid-133310581,imgsize-290354.cms', '2026-08-18T03:34:57+00:00', '2026-08-18T04:01:48.084160'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (367026, 15445, 'The Economic Times', 'en', 'Oil Price Today (August 18): Crude oil crosses $91/barrel amid fading US-Iran peace hopes. What lies ahead?', 'https://economictimes.indiatimes.com/markets/commodities/news/oil-price-today-august-18-crude-oil-crosses-91/barrel-amid-fading-us-iran-peace-hopes-what-lies-ahead/articleshow/133310278.cms', 'Crude oil prices surged past $91 per barrel on Tuesday, August 18, as peace talks between the US and Iran stalled. With shipping disruptions persisting in the Strait of Hormuz, global brokerages like Goldman Sachs and JPMorgan warn Brent crude could scale between $114 and $120 a barrel if supply risks escalate.', 'https://img.etimg.com/photo/msid-133310278,imgsize-46238.cms', '2026-08-18T03:09:46+00:00', '2026-08-18T04:01:48.168595'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
